cat > /workspace/tmp/stress.py <<'EOF'
import ipaddress, json, subprocess, sys, time, random

def addr(value):
    return str(ipaddress.IPv6Address(value))

def big_case(rng, versions=2, runs=64, cache=12, nbursts=4, naddr=64):
    initial=[["::/0",0]]
    for i in range(runs-1):
        initial.append([addr(i+1)+"/128", i+1])
    transactions=[]
    for v in range(versions-1):
        tx=[]
        for i in range(runs-1):
            if rng.random()<0.5:
                tx.append(['erase', addr(i+1)+"/128"])
            else:
                tx.append(['set', addr(i+1)+"/128", rng.randint(0,100)])
        transactions.append(tx)
    bursts=[]
    for b in range(nbursts):
        version=rng.randrange(versions)
        addrs=[addr(rng.getrandbits(128)) for _ in range(naddr)]
        bursts.append({'version':version,'repeat':rng.randint(1,1000),'addresses':addrs})
    return {'initial':initial,'transactions':transactions,'bursts':bursts,'cache_pages':cache,
            'costs':{'hit':1,'miss':17,'decode':[0,1,2]}}

rng=random.Random(5)
tests=[]
tests.append(("2 versions x 64 runs", [big_case(rng, versions=2, runs=64)]))
tests.append(("8 versions x 16 runs", [big_case(rng, versions=8, runs=16)]))
tests.append(("4 cases x 2 versions x 16 runs", [big_case(rng, versions=2, runs=16) for _ in range(4)]))
tests.append(("2 versions x 64 runs, 64 bursts", [big_case(rng, versions=2, runs=64, nbursts=64, naddr=64)]))
case={'initial':[['::/0',0]]+[[addr(i*2**64)+"/64", i] for i in range(1,3000)],
      'transactions':[[['erase',addr(2**64)+"/64"],['set',addr(3*2**64)+"/64",77]]],
      'bursts':[{'version':0,'repeat':3,'addresses':[addr(i*2**64) for i in range(64)]}],
      'cache_pages':12,'costs':{'hit':1,'miss':17,'decode':[0,1,2]}}
tests.append(("3000 routes", [case]))
for label, cases in tests:
    request={'cases':cases}
    payload=json.dumps(request).encode()
    t=time.time()
    p=subprocess.run(['python3','-B','/workspace/submission/main.py'],input=payload,
                     stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    dt=time.time()-t
    if p.returncode:
        print(label,'FAILED',p.stderr.decode()[:800]); continue
    out=json.loads(p.stdout.decode())
    if 'error' in out:
        print(label,'-> invalid', '%.2fs'%dt)
    else:
        print(label,'->', [c['objective'] for c in out['cases']], '%.2fs'%dt, 'outbytes',len(p.stdout))
EOF
cd /workspace && python3 tmp/stress.py
